(defun my-org-html-add-styles ()
  "Add minimal inline styles for org-html export."
  (let ((style-string
         "<style>
  body { font-family: sans-serif; line-height: 1.6; padding: 2rem; }
  img { max-width: 100%; }
  pre { white-space: pre-wrap; }
  table { border-collapse: collapse; }
  th, td { padding: 0.5rem; border: 1px solid #ccc; }
</style>"))
    (insert style-string)
    (newline)))

;; Add the hook
(add-hook 'org-html-before-export-hook #'my-org-html-add-styles)
